<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/functions.php';
require_role('ADMIN');
$pageTitle='Suppliers';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf((string)($_POST['csrf_token']??''))){set_flash('error','Invalid security token.');redirect('/SmartCanteenAI/admin/suppliers.php');}
 try{$id=(int)($_POST['supplier_id']??0);$name=trim((string)$_POST['supplier_name']);$person=trim((string)$_POST['contact_person']);$phone=trim((string)$_POST['phone']);$email=trim((string)$_POST['email']);$address=trim((string)$_POST['address']);$active=isset($_POST['is_active'])?1:0;if($name==='')throw new RuntimeException('Supplier name is required.');if($id){$s=db()->prepare('UPDATE suppliers SET supplier_name=?,contact_person=?,phone=?,email=?,address=?,is_active=? WHERE supplier_id=?');$s->execute([$name,$person?:null,$phone?:null,$email?:null,$address?:null,$active,$id]);set_flash('success','Supplier updated.');}else{$s=db()->prepare('INSERT INTO suppliers(supplier_name,contact_person,phone,email,address,is_active) VALUES(?,?,?,?,?,?)');$s->execute([$name,$person?:null,$phone?:null,$email?:null,$address?:null,$active]);set_flash('success','Supplier created.');}}catch(Throwable $e){set_flash('error',str_contains($e->getMessage(),'Duplicate')?'A duplicate supplier value was entered.':$e->getMessage());}redirect('/SmartCanteenAI/admin/suppliers.php');}
$edit=null;$id=(int)($_GET['edit']??0);if($id){$s=db()->prepare('SELECT * FROM suppliers WHERE supplier_id=?');$s->execute([$id]);$edit=$s->fetch();}
$suppliers=db()->query('SELECT * FROM suppliers ORDER BY supplier_name')->fetchAll();
include __DIR__.'/../includes/header.php';?>
<div class="container-fluid py-4"><div class="mb-4"><h1 class="h3">Suppliers</h1><p class="text-secondary mb-0">Manage ingredient suppliers and contacts.</p></div><div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5"><?=$edit?'Edit Supplier':'Add Supplier'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="supplier_id" value="<?= (int)($edit['supplier_id']??0)?>">
<?php foreach([['supplier_name','Supplier name'],['contact_person','Contact person'],['phone','Phone'],['email','Email'],['address','Address']] as $f):?><div class="mb-3"><label class="form-label"><?=e($f[1])?></label><input class="form-control" name="<?=$f[0]?>" value="<?=e($edit[$f[0]]??'')?>"></div><?php endforeach;?>
<div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="is_active" id="sa" <?=!$edit||(int)$edit['is_active']?'checked':''?>><label class="form-check-label" for="sa">Active</label></div><button class="btn btn-primary">Save</button><?php if($edit):?><a href="/SmartCanteenAI/admin/suppliers.php" class="btn btn-outline-secondary ms-2">Cancel</a><?php endif;?></form></div></div></div>
<div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Supplier</th><th>Contact</th><th>Phone</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($suppliers as $s):?><tr><td><?=e($s['supplier_name'])?></td><td><?=e((string)$s['contact_person'])?></td><td><?=e((string)$s['phone'])?></td><td><?=e((string)$s['email'])?></td><td><?=$s['is_active']?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Inactive</span>'?></td><td><a href="?edit=<?=$s['supplier_id']?>" class="btn btn-sm btn-outline-primary">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></div>
<?php include __DIR__.'/../includes/footer.php';?>